{
  "rules": [
    {
      "id": "F1",
      "text": "WHEN a passenger requests a crossing AND seats are available on the chosen sailing, THE Ferry System SHALL reserve a seat for the passenger.",
      "trigger": "passenger_requests_crossing"
    },
    {
      "id": "F2",
      "text": "WHEN a passenger requests a crossing AND seats are not available on the chosen sailing, THE Ferry System SHALL offer the next sailing with available seats.",
      "trigger": "passenger_requests_crossing"
    },
    {
      "id": "F3",
      "text": "WHEN a passenger pays for a reserved seat, THE Ferry System SHALL send an e-ticket by email.",
      "trigger": "passenger_pays_for_seat"
    },
    {
      "id": "F4",
      "text": "WHEN a reserved seat has been unpaid for more than 30 minutes, THE Ferry System SHALL release the seat.",
      "trigger": ""
    },
    {
      "id": "F5",
      "text": "WHEN a passenger cancels a ticket more than 24 hours before departure, THE Ferry System SHALL refund the full fare.",
      "trigger": "passenger_cancels_ticket"
    },
    {
      "id": "F6",
      "text": "WHEN a passenger cancels a ticket 24 hours or less before departure, THE Ferry System SHALL refund half of the fare.",
      "trigger": "passenger_cancels_ticket"
    },
    {
      "id": "F7",
      "text": "WHEN a passenger moves a ticket to another sailing AND seats are available on the new sailing, THE Ferry System SHALL change the ticket to the new sailing.",
      "trigger": "passenger_moves_ticket"
    },
    {
      "id": "F8",
      "text": "WHEN a passenger moves a ticket to another sailing AND seats are not available on the new sailing, THE Ferry System SHALL leave the ticket on its sailing and show a message.",
      "trigger": "passenger_moves_ticket"
    },
    {
      "id": "F9",
      "text": "WHEN a passenger asks for a printed ticket at the port office, THE Ferry System SHALL print the ticket.",
      "trigger": "passenger_asks_for_printed_ticket"
    },
    {
      "id": "F10",
      "text": "WHEN a passenger books a crossing for a child under 4 years, THE Ferry System SHALL issue a free child ticket.",
      "trigger": "passenger_books_crossing"
    },
    {
      "id": "F11",
      "text": "WHEN a group booking of more than 10 passengers is paid, THE Ferry System SHALL apply a group discount of 10 percent.",
      "trigger": "group_booking_paid"
    },
    {
      "id": "F12",
      "text": "WHEN a passenger enters a discount code AND the code is valid, THE Ferry System SHALL reduce the fare by the amount of the code.",
      "trigger": "passenger_enters_discount_code"
    },
    {
      "id": "F13",
      "text": "WHEN a passenger enters a discount code AND the code is not valid, THE Ferry System SHALL show an error message.",
      "trigger": "passenger_enters_discount_code"
    },
    {
      "id": "F14",
      "text": "WHEN a passenger adds a vehicle to a booking AND space is available on the car deck, THE Ferry System SHALL reserve a vehicle space.",
      "trigger": "passenger_adds_vehicle"
    },
    {
      "id": "F15",
      "text": "WHEN a passenger adds a vehicle to a booking AND space is not available on the car deck, THE Ferry System SHALL put the vehicle on the waiting list.",
      "trigger": "passenger_adds_vehicle"
    },
    {
      "id": "F16",
      "text": "WHEN a passenger adds a vehicle that is taller than 2 metres, THE Ferry System SHALL charge the high-vehicle fare.",
      "trigger": "passenger_adds_vehicle"
    },
    {
      "id": "F17",
      "text": "WHEN a vehicle arrives at the check-in lane AND its number plate matches a booking, THE Ferry System SHALL assign the vehicle to a boarding lane.",
      "trigger": "vehicle_arrives_check_in"
    },
    {
      "id": "F18",
      "text": "WHEN a vehicle arrives at the check-in lane AND its number plate does not match a booking, THE Ferry System SHALL send the driver to the port office.",
      "trigger": "vehicle_arrives_check_in"
    },
    {
      "id": "F19",
      "text": "WHEN a vehicle is assigned to a boarding lane, THE Ferry System SHALL print a lane card for the driver.",
      "trigger": "vehicle_assigned_to_lane"
    },
    {
      "id": "F20",
      "text": "WHEN a driver declares dangerous goods at check-in, THE Ferry System SHALL notify the officer of the watch.",
      "trigger": "driver_declares_dangerous_goods"
    },
    {
      "id": "F21",
      "text": "WHEN a booked vehicle has not checked in 30 minutes before departure, THE Ferry System SHALL release its vehicle space.",
      "trigger": ""
    },
    {
      "id": "F22",
      "text": "WHEN a vehicle space is released AND a vehicle is on the waiting list, THE Ferry System SHALL offer the space to the first vehicle on the waiting list.",
      "trigger": "vehicle_space_released"
    },
    {
      "id": "F23",
      "text": "WHEN a vehicle space is released AND no vehicle is on the waiting list, THE Ferry System SHALL return the space to open sale.",
      "trigger": "vehicle_space_released"
    },
    {
      "id": "F24",
      "text": "WHEN loading of the car deck begins, THE Ferry System SHALL call the boarding lanes in the order of check-in.",
      "trigger": "car_deck_loading_begins"
    },
    {
      "id": "F25",
      "text": "WHEN a vehicle is unloaded at the arrival port, THE Ferry System SHALL mark the vehicle booking as completed.",
      "trigger": "vehicle_unloaded"
    },
    {
      "id": "F26",
      "text": "WHEN a passenger scans an e-ticket at the gate AND the ticket is valid for the next sailing, THE Ferry System SHALL open the gate.",
      "trigger": "passenger_scans_e_ticket"
    },
    {
      "id": "F27",
      "text": "WHEN a passenger scans an e-ticket at the gate AND the ticket is not valid for the next sailing, THE Ferry System SHALL keep the gate closed and show the sailing the ticket is valid for.",
      "trigger": "passenger_scans_e_ticket"
    },
    {
      "id": "F28",
      "text": "WHEN boarding of foot passengers begins, THE Ferry System SHALL announce the boarding in the terminal.",
      "trigger": "foot_passenger_boarding_begins"
    },
    {
      "id": "F29",
      "text": "WHEN boarding closes, THE Ferry System SHALL send the number of boarded passengers to the captain.",
      "trigger": "boarding_closes"
    },
    {
      "id": "F30",
      "text": "WHEN boarding closes AND a ticket holder has not boarded, THE Ferry System SHALL mark the ticket as a no-show.",
      "trigger": "boarding_closes"
    },
    {
      "id": "F31",
      "text": "WHEN a passenger requests boarding assistance while booking, THE Ferry System SHALL book a wheelchair escort for the sailing.",
      "trigger": "passenger_requests_boarding_assistance"
    },
    {
      "id": "F32",
      "text": "WHEN a passenger with booked assistance arrives at the terminal, THE Ferry System SHALL notify the assistance team.",
      "trigger": "passenger_with_assistance_arrives"
    },
    {
      "id": "F33",
      "text": "WHEN a passenger with priority boarding arrives at the terminal, THE Ferry System SHALL direct the passenger to the priority lane.",
      "trigger": "priority_passenger_arrives"
    },
    {
      "id": "F34",
      "text": "WHEN a passenger books a cabin AND a cabin of the requested class is available, THE Ferry System SHALL reserve the cabin.",
      "trigger": "passenger_books_cabin"
    },
    {
      "id": "F35",
      "text": "WHEN a passenger books a cabin AND a cabin of the requested class is not available, THE Ferry System SHALL offer a cabin of another class.",
      "trigger": "passenger_books_cabin"
    },
    {
      "id": "F36",
      "text": "WHEN a passenger with a cabin booking boards the ship, THE Ferry System SHALL send the cabin number and the door code by text message.",
      "trigger": "cabin_passenger_boards"
    },
    {
      "id": "F37",
      "text": "WHEN a passenger enters a door code at a cabin AND the code is correct, THE Ferry System SHALL unlock the cabin door.",
      "trigger": "passenger_enters_door_code"
    },
    {
      "id": "F38",
      "text": "WHEN a passenger enters a door code at a cabin AND the code is not correct, THE Ferry System SHALL keep the cabin door locked.",
      "trigger": "passenger_enters_door_code"
    },
    {
      "id": "F39",
      "text": "WHEN a passenger reports a fault in a cabin, THE Ferry System SHALL create a task for the housekeeping team.",
      "trigger": "passenger_reports_cabin_fault"
    },
    {
      "id": "F40",
      "text": "WHEN a housekeeping task has been open for more than 2 hours, THE Ferry System SHALL alert the purser.",
      "trigger": ""
    },
    {
      "id": "F41",
      "text": "WHEN the ship is 30 minutes from the arrival port, THE Ferry System SHALL remind the cabin passengers to leave their cabins.",
      "trigger": "ship_30_min_from_port"
    },
    {
      "id": "F42",
      "text": "WHEN a passenger orders a wake-up call, THE Ferry System SHALL ring the cabin phone at the requested time.",
      "trigger": "passenger_orders_wake_up_call"
    },
    {
      "id": "F43",
      "text": "WHEN a passenger orders a meal in the restaurant AND the meal is in stock, THE Ferry System SHALL send the order to the kitchen.",
      "trigger": "passenger_orders_meal"
    },
    {
      "id": "F44",
      "text": "WHEN a passenger orders a meal in the restaurant AND the meal is not in stock, THE Ferry System SHALL show the dishes that are in stock.",
      "trigger": "passenger_orders_meal"
    },
    {
      "id": "F45",
      "text": "WHEN the kitchen marks an order as ready, THE Ferry System SHALL show the order number on the restaurant screen.",
      "trigger": "kitchen_marks_order_ready"
    },
    {
      "id": "F46",
      "text": "WHEN a passenger reserves a restaurant table AND a table is free at the requested time, THE Ferry System SHALL confirm the reservation.",
      "trigger": "passenger_reserves_table"
    },
    {
      "id": "F47",
      "text": "WHEN a passenger reserves a restaurant table AND no table is free at the requested time, THE Ferry System SHALL offer the nearest time with a free table.",
      "trigger": "passenger_reserves_table"
    },
    {
      "id": "F48",
      "text": "WHEN a passenger charges a shop purchase to the cabin, THE Ferry System SHALL add the amount to the cabin bill.",
      "trigger": "passenger_charges_to_cabin"
    },
    {
      "id": "F49",
      "text": "WHEN a passenger pays in the shop by bank card AND the payment is approved, THE Ferry System SHALL print a receipt.",
      "trigger": "passenger_pays_by_card"
    },
    {
      "id": "F50",
      "text": "WHEN a passenger pays in the shop by bank card AND the payment is not approved, THE Ferry System SHALL cancel the sale and show a message.",
      "trigger": "passenger_pays_by_card"
    },
    {
      "id": "F51",
      "text": "WHEN a passenger buys alcohol in the shop, THE Ferry System SHALL ask the cashier to check the passenger's age.",
      "trigger": "passenger_buys_alcohol"
    },
    {
      "id": "F52",
      "text": "WHEN the ship enters the waters of the arrival country, THE Ferry System SHALL switch the shop prices to the tax rate of the arrival country.",
      "trigger": "ship_enters_arrival_waters"
    },
    {
      "id": "F53",
      "text": "WHEN the stock of a product in the shop falls below 5 units, THE Ferry System SHALL add the product to the restocking list.",
      "trigger": ""
    },
    {
      "id": "F54",
      "text": "WHEN the shop closes, THE Ferry System SHALL send the day's sales to the head office.",
      "trigger": "shop_closes"
    },
    {
      "id": "F55",
      "text": "WHEN a passenger orders room service AND the passenger has a cabin, THE Ferry System SHALL deliver the order to the cabin.",
      "trigger": "passenger_orders_room_service"
    },
    {
      "id": "F56",
      "text": "WHEN a passenger orders room service AND the passenger does not have a cabin, THE Ferry System SHALL refuse the order and suggest the restaurant.",
      "trigger": "passenger_orders_room_service"
    },
    {
      "id": "F57",
      "text": "WHEN a passenger connects to the onboard Wi-Fi, THE Ferry System SHALL show the login page.",
      "trigger": "passenger_connects_wifi"
    },
    {
      "id": "F58",
      "text": "WHEN a passenger buys a Wi-Fi pass, THE Ferry System SHALL send the pass code by text message.",
      "trigger": "passenger_buys_wifi_pass"
    },
    {
      "id": "F59",
      "text": "WHEN a passenger logs in to the Wi-Fi AND the passenger has a valid Wi-Fi pass, THE Ferry System SHALL give internet access until the end of the crossing.",
      "trigger": "passenger_logs_in_wifi"
    },
    {
      "id": "F60",
      "text": "WHEN a passenger logs in to the Wi-Fi AND the passenger does not have a valid Wi-Fi pass, THE Ferry System SHALL offer a free 15-minute session.",
      "trigger": "passenger_logs_in_wifi"
    },
    {
      "id": "F61",
      "text": "WHEN a passenger books a cinema seat AND seats are left for the film, THE Ferry System SHALL reserve the cinema seat.",
      "trigger": "passenger_books_cinema_seat"
    },
    {
      "id": "F62",
      "text": "WHEN a passenger books a cinema seat AND no seats are left for the film, THE Ferry System SHALL show the next showing of the film.",
      "trigger": "passenger_books_cinema_seat"
    },
    {
      "id": "F63",
      "text": "WHEN a film is 10 minutes from its start, THE Ferry System SHALL announce the film on the cabin screens.",
      "trigger": "film_10_min_from_start"
    },
    {
      "id": "F64",
      "text": "WHEN a parent registers a child for the kids' club, THE Ferry System SHALL give the parent a pager.",
      "trigger": "parent_registers_child"
    },
    {
      "id": "F65",
      "text": "WHEN the kids' club calls a parent, THE Ferry System SHALL make the parent's pager vibrate.",
      "trigger": "kids_club_calls_parent"
    },
    {
      "id": "F66",
      "text": "WHEN a passenger adds a pet to a booking AND a kennel is available, THE Ferry System SHALL reserve a kennel.",
      "trigger": "passenger_adds_pet"
    },
    {
      "id": "F67",
      "text": "WHEN a passenger adds a pet to a booking AND a kennel is not available, THE Ferry System SHALL offer a pet-friendly cabin.",
      "trigger": "passenger_adds_pet"
    },
    {
      "id": "F68",
      "text": "WHEN a passenger adds a pet to a booking, THE Ferry System SHALL add the pet fee to the fare.",
      "trigger": "passenger_adds_pet"
    },
    {
      "id": "F69",
      "text": "WHEN a passenger with a pet checks in AND the pet's vaccination record is valid, THE Ferry System SHALL issue a pet tag.",
      "trigger": "passenger_with_pet_checks_in"
    },
    {
      "id": "F70",
      "text": "WHEN a passenger with a pet checks in AND the pet's vaccination record is not valid, THE Ferry System SHALL refuse the pet and notify the port office.",
      "trigger": "passenger_with_pet_checks_in"
    },
    {
      "id": "F71",
      "text": "WHEN the ship has docked at the arrival port, THE Ferry System SHALL tell the passengers with kennels that they can collect their pets.",
      "trigger": "ship_docked_arrival"
    },
    {
      "id": "F72",
      "text": "WHEN the weather service issues a storm warning for a route, THE Ferry System SHALL notify the operations manager.",
      "trigger": "storm_warning_issued"
    },
    {
      "id": "F73",
      "text": "WHEN the operator cancels a sailing, THE Ferry System SHALL notify all booked passengers by text message.",
      "trigger": "operator_cancels_sailing"
    },
    {
      "id": "F74",
      "text": "WHEN the operator cancels a sailing, THE Ferry System SHALL offer every booked passenger a free rebooking or a full refund.",
      "trigger": "operator_cancels_sailing"
    },
    {
      "id": "F75",
      "text": "WHEN a sailing is delayed by more than 60 minutes, THE Ferry System SHALL give each passenger a meal voucher.",
      "trigger": "sailing_delayed"
    },
    {
      "id": "F76",
      "text": "WHEN a sailing is delayed by more than 120 minutes, THE Ferry System SHALL give each passenger a travel voucher worth 25 percent of the fare.",
      "trigger": "sailing_delayed"
    },
    {
      "id": "F77",
      "text": "WHEN a delay of a sailing is announced, THE Ferry System SHALL update the departure board.",
      "trigger": "delay_announced"
    },
    {
      "id": "F78",
      "text": "WHEN a passenger asks for a delay certificate, THE Ferry System SHALL email a certificate that states the delay.",
      "trigger": "passenger_asks_delay_certificate"
    },
    {
      "id": "F79",
      "text": "WHEN a customer creates an account, THE Ferry System SHALL send a welcome email.",
      "trigger": "customer_creates_account"
    },
    {
      "id": "F80",
      "text": "WHEN a customer with an account completes a crossing, THE Ferry System SHALL add loyalty points for the fare paid.",
      "trigger": "customer_completes_crossing"
    },
    {
      "id": "F81",
      "text": "WHEN a customer completes the tenth crossing of a calendar year, THE Ferry System SHALL upgrade the customer to silver status.",
      "trigger": "customer_completes_crossing"
    },
    {
      "id": "F82",
      "text": "WHEN a silver customer books a crossing, THE Ferry System SHALL give the customer priority boarding.",
      "trigger": "customer_books_crossing"
    },
    {
      "id": "F83",
      "text": "WHEN a customer pays with loyalty points AND the points cover the fare, THE Ferry System SHALL take the points and issue the ticket.",
      "trigger": "customer_pays_with_points"
    },
    {
      "id": "F84",
      "text": "WHEN a customer pays with loyalty points AND the points do not cover the fare, THE Ferry System SHALL ask the customer to pay the difference by card.",
      "trigger": "customer_pays_with_points"
    },
    {
      "id": "F85",
      "text": "WHEN a customer changes the email address of the account, THE Ferry System SHALL send a confirmation link to the new address.",
      "trigger": "customer_changes_email"
    },
    {
      "id": "F86",
      "text": "WHEN a customer enters a wrong password for the third time in a row, THE Ferry System SHALL lock the account for 15 minutes.",
      "trigger": "wrong_password_entered"
    },
    {
      "id": "F87",
      "text": "WHEN a customer subscribes to the newsletter, THE Ferry System SHALL send a confirmation email.",
      "trigger": "customer_subscribes_newsletter"
    },
    {
      "id": "F88",
      "text": "WHEN a customer unsubscribes from the newsletter, THE Ferry System SHALL confirm the unsubscription by email.",
      "trigger": "customer_unsubscribes_newsletter"
    },
    {
      "id": "F89",
      "text": "WHEN a crew member registers a found item, THE Ferry System SHALL record the description of the item and the sailing.",
      "trigger": "crew_registers_found_item"
    },
    {
      "id": "F90",
      "text": "WHEN a passenger reports a lost item AND a matching found item is registered, THE Ferry System SHALL tell the passenger where to collect it.",
      "trigger": "passenger_reports_lost_item"
    },
    {
      "id": "F91",
      "text": "WHEN a passenger reports a lost item AND no matching found item is registered, THE Ferry System SHALL record the report and send a reply within 3 days.",
      "trigger": "passenger_reports_lost_item"
    },
    {
      "id": "F92",
      "text": "WHEN a found item has been unclaimed for more than 90 days, THE Ferry System SHALL hand the item over to a charity.",
      "trigger": ""
    },
    {
      "id": "F93",
      "text": "WHEN a crew member presses the man-overboard button, THE Ferry System SHALL sound the alarm on the bridge and record the ship's position.",
      "trigger": "man_overboard_button_pressed"
    },
    {
      "id": "F94",
      "text": "WHEN a fire detector raises an alarm, THE Ferry System SHALL show the location of the detector on the bridge panel.",
      "trigger": "fire_detector_alarm"
    },
    {
      "id": "F95",
      "text": "WHEN a crew member starts a shift, THE Ferry System SHALL record the start time.",
      "trigger": "crew_starts_shift"
    },
    {
      "id": "F96",
      "text": "WHEN a crew member has worked more than 12 hours in one shift, THE Ferry System SHALL alert the chief officer.",
      "trigger": ""
    },
    {
      "id": "F97",
      "text": "WHEN the ship has docked at the arrival port, THE Ferry System SHALL announce that passengers may leave the ship.",
      "trigger": "ship_docked_arrival"
    },
    {
      "id": "F98",
      "text": "WHEN a passenger leaves the ship, THE Ferry System SHALL mark the ticket as used.",
      "trigger": "passenger_leaves_ship"
    },
    {
      "id": "F99",
      "text": "WHEN a passenger asks for an invoice, THE Ferry System SHALL email an invoice with the company's tax number.",
      "trigger": "passenger_asks_invoice"
    },
    {
      "id": "F100",
      "text": "WHEN a passenger writes a review after the crossing, THE Ferry System SHALL publish the review on the route page.",
      "trigger": "passenger_writes_review"
    }
  ],
